INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Çocuk Diş Hekimliği: İlk Muayene, Süt Dişi Çürüğü ve Koruyucu Bakım',
'<p>Çocuğun ilk diş hekimi muayenesi, ilk süt dişi çıktıktan sonraki altı ay içinde ya da en geç birinci yaş gününde önerilir. Bu ziyaretin amacı çoğu zaman tedavi değil; çürük riskini değerlendirmek, aileye yaşa uygun bakım ve beslenme bilgisi vermek ve çocuğun kliniğe alışmasını sağlamaktır. Erken tanışan çocukta ileride tedavi gerekirse süreç genellikle daha kolay yönetilir.</p>
<p><img src="/assets/uploads/images/ts87-01-ilk-muayene-kucuk-cocuk.webp" alt="Küçük bir çocuğun diş ünitinde ilk muayenesi" loading="lazy" /></p>
<p>Kliniğimizde çocuk hastalarımız pedodonti uzmanı hekimimiz tarafından değerlendirilir ve tedavi edilir.</p>
<h2>Süt dişleri neden önemlidir?</h2>
<p>Süt dişleri yalnız geçici bir dizi değildir; çiğneme, konuşma gelişimi ve daimi dişler için yer korunması açısından işlev görür. Erken kaybedilen bir süt dişinin boşluğuna komşu dişler kayabilir ve daimi diş için gereken yer daralabilir.</p>
<table>
<thead><tr><th>İşlev</th><th>Açıklama</th></tr></thead>
<tbody>
<tr><td>Çiğneme ve beslenme</td><td>Ağrılı veya çürük diş, çocuğun çiğnemesini ve beslenme çeşitliliğini sınırlayabilir.</td></tr>
<tr><td>Konuşma gelişimi</td><td>Ön bölge dişleri bazı seslerin oluşumuna katkıda bulunur.</td></tr>
<tr><td>Yer koruma</td><td>Her süt dişi, altındaki daimi diş için yer tutar. Erken kayıpta yer daralması görülebilir.</td></tr>
<tr><td>Çene gelişimi</td><td>Dengeli çiğneme, çene ve kas gelişimini destekler.</td></tr>
</tbody>
</table>
<h2>Süt dişi çürüğü nasıl başlar, nasıl fark edilir?</h2>
<p>Süt dişi minesi daimi dişe göre daha incedir; bu nedenle <a href="/dis-curugu-kompozit-dolgu/">çürük</a> bazı çocuklarda daha hızlı ilerleyebilir. Erken dönemde ağrı olmayabilir, bu yüzden ağrı beklemeden düzenli kontrol önemlidir.</p>
<ul>
<li>Diş eti sınırına yakın bölgede tebeşirimsi beyaz lekeler (başlangıç bulgusu)</li>
<li>Kahverengi–siyah renk değişikliği, yüzeyde çukurlaşma</li>
<li>Soğuk, sıcak veya tatlıyla gelen hassasiyet</li>
<li>Çocuğun bir tarafla çiğnemekten kaçınması</li>
<li>Diş etinde şişlik, yüzde şişlik veya ateş — bu durumda beklenmez</li>
</ul>
<p><img src="/assets/uploads/images/ts87-02-sut-disi-curuk-asamalari.webp" alt="Süt dişi çürüğünün başlangıç lekesinden ileri evreye aşamaları" loading="lazy" /></p>
<p><strong>Biberon ve gece emzirme:</strong> Uyku sırasında biberonla şekerli içecek, meyve suyu veya sık gece emzirmesi, ön dişlerde hızlı ilerleyen çürüklerle ilişkilendirilir. Su dışındaki içecekler uyku öncesinde ve uyku sırasında verilmemelidir.</p>
<h2>Yaşa göre ağız bakımı ve florür</h2>
<p>Fırçalama, ilk diş ağızda göründüğü anda başlar. Küçük çocuklarda fırçalamayı ebeveyn yapar; okul çağında çocuk kendi fırçalasa bile ebeveyn kontrolü ve desteği sürer.</p>
<table>
<thead><tr><th>Yaş</th><th>Yaklaşım</th></tr></thead>
<tbody>
<tr><td>İlk diş – 3 yaş</td><td>Günde iki kez, yumuşak kıllı küçük başlıklı fırça. Florürlü macun pirinç tanesi kadar (ince bir sürüntü) miktarda. Fırçalamayı ebeveyn yapar.</td></tr>
<tr><td>3 – 6 yaş</td><td>Günde iki kez, bezelye tanesi kadar florürlü macun. Çocuk fırçalar, ebeveyn tamamlar ve denetler. Macunu tükürmesi öğretilir, çalkalanmaz.</td></tr>
<tr><td>6 yaş ve üzeri</td><td>Günde iki kez fırçalama, temas eden yüzeylerde diş ipi. Ebeveyn denetimi azalarak sürer.</td></tr>
<tr><td>Tüm yaşlar</td><td>Macun tüpü çocuğun erişemeyeceği yerde tutulur; macun yutulmamalıdır.</td></tr>
</tbody>
</table>
<p>Uygun macun miktarı ve florür gereksinimi çocuğun yaşına ve çürük riskine göre hekim tarafından belirlenir.</p>
<p><img src="/assets/uploads/images/ts87-03-yasa-gore-macun-miktari.webp" alt="Yaşa göre diş macunu miktarı: pirinç tanesi ve bezelye tanesi karşılaştırması" loading="lazy" /></p>
<h2>Koruyucu uygulamalar</h2>
<table>
<thead><tr><th>Uygulama</th><th>Ne zaman değerlendirilir?</th></tr></thead>
<tbody>
<tr><td>Fissür örtücü</td><td>Azı dişlerinin çiğneyici yüzeyindeki derin girintiler temizlenmesi zor olduğunda; diş sürdükten sonra, çürük yokken uygulanır.</td></tr>
<tr><td>Florür verniği</td><td>Çürük riski değerlendirmesine göre, belirli aralıklarla klinikte uygulanabilir. Her çocuk için aynı sıklıkta değildir.</td></tr>
<tr><td>Beslenme danışmanlığı</td><td>Şeker sıklığı, atıştırma düzeni ve içecek seçimleri gözden geçirilir.</td></tr>
<tr><td>Fırçalama eğitimi</td><td>Çocuğun el becerisine ve yaşına göre teknik gösterilir; ebeveynin rolü tanımlanır.</td></tr>
</tbody>
</table>
<p>Fissür örtücü, florür uygulaması, yer tutucu ve koruyucu rezin restorasyonların tamamı kliniğimizde uygulanmaktadır.</p>
<p><img src="/assets/uploads/images/ts87-04-fissur-orturucu.webp" alt="Azı dişinin çiğneyici yüzeyine uygulanan fissür örtücü" loading="lazy" /></p>
<h2>Diş kaybı ve yer tutucu</h2>
<p>Bir süt dişi çürük veya travma nedeniyle zamanından önce kaybedilirse, komşu dişlerin boşluğa kaymasını sınırlamak için yer tutucu değerlendirilebilir. Her erken kayıpta yer tutucu gerekmez; karar, kaybedilen dişin hangi diş olduğuna, çocuğun yaşına, altındaki daimi dişin gelişim aşamasına ve radyografik bulgulara göre verilir.</p>
<h2>Çocuğu randevuya hazırlamak</h2>
<ul>
<li>Randevudan önce ayrıntılı korku hikâyesi anlatmak yerine, ziyaretin &laquo;dişleri saymak&raquo; gibi sakin bir çerçeveyle tanıtılması önerilir.</li>
<li>&laquo;Acımayacak&raquo;, &laquo;iğne yok&raquo; gibi kesin sözler verilmemesi, güvenin korunması açısından önemlidir.</li>
<li>Randevu saatinin çocuğun dinlenmiş olduğu bir zamana alınması işbirliğini kolaylaştırır.</li>
<li>Önceki olumsuz deneyimler, varsa özel gereksinim durumu ve kullanılan ilaçlar randevu öncesinde paylaşılmalıdır.</li>
</ul>
<p>Belirgin kaygısı olan çocuklarda aşamalı alıştırma yaklaşımı izlenir. Tedaviye uyum sağlamakta zorlanan, çok küçük yaştaki ya da kapsamlı tedavi gereksinimi olan çocuklarda sedasyon altında tedavi uygulanır; sedasyon uygulaması kliniğimizde yapılmaktadır. Genel anestezi gerektiren durumlarda tedavi, anlaşmalı hastanelerimizde anestezi uzmanı eşliğinde ve yine kliniğimizin pedodonti uzmanı hekimi tarafından gerçekleştirilir. Uygulanacak yöntem çocuğun yaşı, genel sağlık durumu ve tedavi kapsamı değerlendirilerek aileyle birlikte kararlaştırılır.</p>
<h2>Sık sorulan sorular</h2>
<p><strong>Çocuğumu ilk kez ne zaman diş hekimine götürmeliyim?</strong><br>İlk süt dişi çıktıktan sonraki altı ay içinde, en geç birinci yaş gününde önerilir. Şikâyet olmasa da bu ziyaret çürük riskini değerlendirmek ve bakım planı kurmak için yapılır.</p>
<p><strong>Süt dişi nasılsa düşecek, çürüğü tedavi edilmeli mi?</strong><br>Evet. Tedavi edilmeyen çürük ağrıya, enfeksiyona, beslenme sorununa ve erken diş kaybına yol açabilir; erken kayıp daimi dişin yerini etkileyebilir.</p>
<p><strong>Florürlü macun çocuk için güvenli mi?</strong><br>Yaşa uygun miktarda ve denetimli kullanıldığında florürlü macun çürükten korunmada yararlı kabul edilir. Önemli olan miktarın yaşa uygun olması ve macunun yutulmamasıdır.</p>
<p><strong>Çocuğumun dişleri arasında boşluk var, sorun mu?</strong><br>Süt dişlenmesinde aralıklar çoğu zaman beklenen bir durumdur ve daimi dişler için yer sağlar. Yine de değerlendirme muayeneyle yapılır.</p>
<p><strong>Parmak emme veya emzik dişleri bozar mı?</strong><br>Süre ve yoğunluğa bağlı olarak kapanış ilişkisini etkileyebilir. Alışkanlığın devam ettiği durumlarda yaşa uygun bırakma yaklaşımı değerlendirilir.</p>
<p><strong>Çocuk diş hekimliği ile ortodonti aynı şey mi?</strong><br>Hayır. Çocuk diş hekimliği çürük, koruyucu bakım ve süt dişi tedavilerini kapsar; diş ve çene dizilimi ise ortodontik değerlendirmenin konusudur.</p>
<h2>Yerel değerlendirme</h2>
<p>Beylikdüzü/Esenyurt bağlantısındaki kliniğimizde çocuk hastalarda öncelik, ağrısız dönemde tanışma ve çürük riskinin erken belirlenmesidir. Tedavi gereksinimi; klinik muayene, çocuğun yaşı, işbirliği düzeyi ve gerekli görüntüleme bulguları birlikte değerlendirilerek planlanır.</p>
<p><a href="/agiz-dis-sagligi/">Ağız ve Diş Sağlığı</a> · <a href="/dis-curugu-kompozit-dolgu/">Diş Çürüğü ve Kompozit Dolgu</a> · <a href="/kanal-tedavisi/">Kanal Tedavisi</a> · <a href="/iletisim">Randevu ve iletişim</a></p>',
'Çocuklarda ilk diş muayenesi ne zaman yapılmalı, süt dişi çürüğü neden önemli, florür ve yer tutucu hangi durumlarda gerekir? Aileler için rehber.',
'Çocuk Diş Hekimliği | MSc. Dt. Mehmet Taş',
'TR'
FROM pages WHERE link = 'cocuk-dis-hekimligi';
